do
    local function buildCombatControls()
        local combatAim=tab:AddSection("SILENT AIM", "Server FireServer redirect")
        combatAim:AddToggle("Enabled", toggle)
        combatAim:AddToggle("Wall Check", function(v) config.wallCheck=v==true end)
        combatAim:AddToggle("Show Shoot Murder Button", setShootButtonVisible)
        combatAim:AddToggle("Lock Shoot Murder Button", function(v) config.lockShootButton=v==true end)

         
        do
            local globals = NoirGenv()
            local oldPrediction = globals.__NoirPredictionRuntime
            if type(oldPrediction) == "table" and type(oldPrediction.Stop) == "function" then pcall(oldPrediction.Stop) end
            local oldOmega = globals.__NoirOmegaRuntime
            if type(oldOmega) == "table" and type(oldOmega.Stop) == "function" then pcall(oldOmega.Stop) end
            globals.__NoirOmegaRuntime = nil

            local SAMPLE_INTERVAL = 0.4
            local MONITOR_INTERVAL = 0.25
            local STALE_INTERVAL = 5
            local HYSTERESIS = 4
            local statsService = game:GetService("Stats")
            local profileState = {
                alive = true, initializing = true,
                enabled = false, adaptive = true, locked = false, upgrade = false, monitor = false, fpsBoost = false,
                lastApply = -math.huge, currentProfile = "--", classicIndex = nil,
                rawPing = 60, smoothedPing = 60, jitter = 0, pingSource = "Fallback",
                lastAttempt = -math.huge, lastGoodSample = -math.huge,
                workerToken = nil, monitorGui = nil, monitorLabels = nil, lastSummary = nil,
            }

            local function warnOnce(key, message)
                profileState.warnings = profileState.warnings or {}
                if not profileState.warnings[key] then
                    profileState.warnings[key] = true
                    warn("[Noir Auto] " .. message)
                end
            end
            local function isFinite(value)
                return type(value) == "number" and value == value
                    and value > -math.huge and value < math.huge
            end
            local function readStat(folderName, itemName)
                local folder = statsService:FindFirstChild(folderName)
                local item = folder and folder:FindFirstChild(itemName)
                if not item then return nil end
                local ok, value = pcall(function() return item:GetValue() end)
                return ok and value or nil
            end
            local function readNetworkPing()
                local ok, value = pcall(function() return LocalPlayer:GetNetworkPing() end)
                if ok and isFinite(value) then return value * 1000 end
            end
            local pingReaders = {
                { function() return readStat("Network", "Data Ping") end, "Data Ping" },
                { function() return readStat("PerformanceStats", "Ping") end, "Performance" },
                { readNetworkPing, "Network" },
            }
            local function samplePing(force)
                local now = os.clock()
                if not force and now - profileState.lastAttempt < SAMPLE_INTERVAL then return end
                profileState.lastAttempt = now
                local value
                for _, reader in ipairs(pingReaders) do
                    local ok, candidate = pcall(reader[1])
                    if ok and isFinite(candidate) and candidate > 0 then
                        value = candidate
                        profileState.pingSource = reader[2]
                        break
                    end
                end
                if not value then
                    profileState.pingSource = profileState.lastGoodSample == -math.huge and "Fallback" or "Last known"
                    return
                end
                local elapsed = now - profileState.lastGoodSample
                local nextRaw = math.clamp(math.floor(value + 0.5), 5, 1200)
                if elapsed > STALE_INTERVAL then
                    profileState.smoothedPing = nextRaw
                    profileState.jitter = 0
                else
                    local weight = elapsed / SAMPLE_INTERVAL
                    local jitterAlpha = 1 - 0.75 ^ weight
                    profileState.jitter = profileState.jitter
                        + (math.abs(nextRaw - profileState.rawPing) - profileState.jitter) * jitterAlpha
                    if profileState.adaptive then
                        local alpha = math.abs(nextRaw - profileState.smoothedPing) > 40 and 0.6 or 0.25
                        alpha = 1 - (1 - alpha) ^ weight
                        profileState.smoothedPing = profileState.smoothedPing
                            + (nextRaw - profileState.smoothedPing) * alpha
                    else
                        profileState.smoothedPing = nextRaw
                    end
                end
                profileState.rawPing = nextRaw
                profileState.lastGoodSample = now
            end
            local function getPing()
                return math.floor(profileState.smoothedPing + 0.5)
            end
            local function getConfig(ping)
                local first, second, blend, name
                if profileState.adaptive then
                    name = "Dynamic " .. tostring(math.floor(ping)) .. " ms"
                    first, second = PingProfiles[1], PingProfiles[1]
                    if ping >= PingProfiles[#PingProfiles].Ping then
                        first, second = PingProfiles[#PingProfiles], PingProfiles[#PingProfiles]
                    elseif ping > first.Ping then
                        for i = 1, #PingProfiles - 1 do
                            if ping <= PingProfiles[i + 1].Ping then
                                first, second = PingProfiles[i], PingProfiles[i + 1]
                                blend = (ping - first.Ping) / (second.Ping - first.Ping)
                                blend = blend * blend * (3 - 2 * blend)
                                break
                            end
                        end
                    end
                    blend = blend or 0
                else
                    local thresholds = { 50, 100, 150 }
                    local index = profileState.classicIndex
                    if index then
                        while index < 4 and ping > thresholds[index] + HYSTERESIS do index += 1 end
                        while index > 1 and ping <= thresholds[index - 1] - HYSTERESIS do index -= 1 end
                    else
                        index = 1
                        while index < 4 and ping > thresholds[index] do index += 1 end
                    end
                    profileState.classicIndex = index
                    first = PingProfiles[index + 1] or PingProfiles[#PingProfiles]
                    second, blend = first, 0
                    name = "Classic " .. string.char(64 + index)
                end
                local function mix(key, scale)
                    local value = first[key] + (second[key] - first[key]) * blend
                    scale = scale or 1
                    return math.floor(value * scale + 0.5) / scale
                end
                local result = {
                    Name = name,
                    Sim = mix("Sim"), Interval = mix("Interval"),
                    H = mix("H"), V = mix("V"),
                    X = mix("X"), Y = mix("Y"), Z = mix("Z"),
                }
                if profileState.upgrade then
                    result.Sim += 1
                    result.H += 2
                    result.V += 2
                end
                return result
            end

            local statusControl
            local function tr(value)
                if type(NoirTr) == "function" then return NoirTr(value) end
                return value
            end
            local function displayProfile()
                if profileState.currentProfile == "--" then return "--" end
                local letter = string.match(profileState.currentProfile, "Classic ([A-D])$")
                if letter then return tr("Classic") .. " " .. letter end
                return tr("Dynamic") .. " " .. tostring(getPing()) .. " " .. tr("ms")
            end
            local function setText(labelObject, value)
                if labelObject and labelObject.Parent and labelObject.Text ~= value then labelObject.Text = value end
            end
            local function statusText()
                local mode = profileState.adaptive and tr("Adaptive") or tr("Classic")
                local current = not profileState.enabled and tr("OFF")
                    or profileState.locked and tr("LOCKED") or tr("ON")
                return string.format("%s: %s | %d %s | %s | %s%s",
                    tr("Noir Auto"), current, getPing(), tr("ms"), mode, displayProfile(),
                    profileState.upgrade and (" " .. tr("+Upgrade")) or "")
            end
            local function refreshStatus()
                local summary = statusText()
                if statusControl and type(statusControl.SetValue) == "function"
                    and profileState.lastSummary ~= summary then
                    profileState.lastSummary = summary
                    statusControl:SetValue(summary)
                end
                local labels = profileState.monitorLabels
                if labels then
                    local mode = profileState.adaptive and tr("Adaptive") or tr("Classic")
                    local current = not profileState.enabled and tr("OFF")
                        or profileState.locked and tr("LOCKED") or tr("ON")
                    setText(labels.state, current .. " " .. mode .. (profileState.upgrade and " " .. tr("UPGRADE") or ""))
                    setText(labels.config, tostring(getPing()) .. " " .. tr("ms") .. " " .. displayProfile())
                    setText(labels.values, string.format("S:%s I:%s H/V:%s/%s",
                        tostring(config.maxSimulationMs), tostring(config.predictionIntervalMs),
                        tostring(config.horizontalMultiplier), tostring(config.verticalMultiplier)))
                    setText(labels.source, tr("Jitter") .. ": " .. tostring(math.floor(profileState.jitter + 0.5))
                        .. " " .. tr("ms") .. " " .. tr(profileState.pingSource))
                end
            end
            local function destroyMonitor()
                if profileState.monitorGui then
                    pcall(function() profileState.monitorGui:Destroy() end)
                    profileState.monitorGui = nil
                end
                profileState.monitorLabels = nil
                local parent = guiParent
                if typeof(parent) ~= "Instance" then
                    parent = LocalPlayer:FindFirstChildOfClass("PlayerGui")
                end
                if parent then
                    local stale = parent:FindFirstChild("NoirAutoPredictionMonitor")
                    if stale then pcall(function() stale:Destroy() end) end
                end
            end
            local function createMonitor()
                if profileState.monitorGui and profileState.monitorGui.Parent then return end
                destroyMonitor()
                local parent = guiParent
                if typeof(parent) ~= "Instance" then parent = LocalPlayer:FindFirstChildOfClass("PlayerGui") end
                if typeof(parent) ~= "Instance" then
                    warnOnce("monitor-parent", "Monitor UI parent is unavailable.")
                    profileState.monitor = false
                    return
                end
                local screen = New("ScreenGui", {
                    Parent = parent, Name = "NoirAutoPredictionMonitor", ResetOnSpawn = false,
                    IgnoreGuiInset = true, DisplayOrder = 82, ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
                })
                local card = New("Frame", {
                    Parent = screen, AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -8, 0, 54),
                    Size = UDim2.fromOffset(205, 82), BackgroundColor3 = Color3.fromRGB(10, 12, 16),
                    BackgroundTransparency = 0.22, BorderSizePixel = 0, ClipsDescendants = true,
                })
                corner(card, 11)
                stroke(card, C.accent, 0.62)
                local function line(name, y, color, size, bold)
                    return New("TextLabel", {
                        Parent = card, Name = name, Position = UDim2.fromOffset(10, y),
                        Size = UDim2.new(1, -20, 0, 14), BackgroundTransparency = 1,
                        Text = "", TextColor3 = color, TextSize = size,
                        Font = bold and Enum.Font.GothamBold or Enum.Font.Gotham,
                        TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd,
                    })
                end
                line("Title", 4, C.text, 9, true).Text = tr("NOIR AUTO PREDICTION")
                profileState.monitorGui = screen
                profileState.monitorLabels = {
                    state = line("State", 19, C.dim, 8, false),
                    config = line("Profile", 34, C.dim, 8, false),
                    values = line("Values", 49, C.dim, 8, false),
                    source = line("Source", 64, C.dim, 7, false),
                }
                refreshStatus()
            end
            local function syncControl(key, value)
                local control = noirMirrorControls["pistol." .. key]
                if type(control) ~= "table" or type(control.SetValue) ~= "function" then return end
                local ok, current = pcall(function() return control:GetValue() end)
                if ok and tonumber(current) == tonumber(value) then return end
                -- Auto ping is transient; update the slider without writing a file every sample.
                pcall(function() control:SetValue(value, false) end)
            end
            local function syncControls(profile, ping)
                config.maxSimulationMs = profile.Sim
                config.predictionIntervalMs = profile.Interval
                config.offsetX, config.offsetY, config.offsetZ = profile.X, profile.Y, profile.Z
                config.horizontalMultiplier, config.verticalMultiplier = profile.H, profile.V
                config.manualPingMs = ping
                syncControl("maxSimulationMs", profile.Sim)
                syncControl("predictionIntervalMs", profile.Interval)
                syncControl("offsetX", profile.X)
                syncControl("offsetY", profile.Y)
                syncControl("offsetZ", profile.Z)
                syncControl("horizontalMultiplier", profile.H)
                syncControl("verticalMultiplier", profile.V)
                syncControl("manualPingMs", ping)
            end
            local function applyProfile(force)
                if not profileState.alive then return end
                local now = os.clock()
                if not force and now - profileState.lastApply < SAMPLE_INTERVAL then return end
                profileState.lastApply = now
                samplePing(force == true)
                if not profileState.enabled or profileState.locked then
                    refreshStatus()
                    return
                end
                local ping = getPing()
                local values = getConfig(ping)
                syncControls(values, ping)
                profileState.currentProfile = values.Name
                profileState.applyHealthy = true
                refreshStatus()
            end
            local function needsUpdates()
                return profileState.monitor or (profileState.enabled and not profileState.locked)
            end
            local function syncWorker()
                if not profileState.alive or not needsUpdates() then
                    profileState.workerToken = nil
                    return
                end
                if profileState.workerToken then return end
                local token = {}
                profileState.workerToken = token
                task.spawn(function()
                    while profileState.alive and profileState.workerToken == token and needsUpdates() do
                        task.wait(profileState.monitor and MONITOR_INTERVAL or SAMPLE_INTERVAL)
                        if profileState.alive and profileState.workerToken == token and needsUpdates() then
                            if profileState.enabled and not profileState.locked then
                                applyProfile(false)
                            else
                                samplePing(false)
                            end
                            refreshStatus()
                        end
                    end
                end)
            end
            local function reconfigure(invalidate)
                if invalidate then profileState.lastApply = -math.huge end
                if profileState.enabled and not profileState.locked then
                    applyProfile(true)
                else
                    refreshStatus()
                end
                syncWorker()
            end
            local function telemetry()
                samplePing(true)
                if profileState.enabled and not profileState.locked then applyProfile(true) end
                local mode = profileState.adaptive and tr("Adaptive") or tr("Classic")
                local summary = string.format("%s=%d %s | %s=%d | %s=%d | %s=%s | %s=%s | %s=%s",
                    tr("Ping"), getPing(), tr("ms"), tr("Raw"), profileState.rawPing,
                    tr("Jitter"), math.floor(profileState.jitter + 0.5), tr("Source"), tr(profileState.pingSource),
                    tr("Profile"), displayProfile(), tr("Mode"), mode)
                notify(summary, 4)
                print("[Noir Auto] " .. summary)
            end

            local persistence = NoirPersistence and NoirPersistence.data and NoirPersistence.data.toggles
            local profileFpsKey = "Noir Auto prediction profile::FPS Boost"
            local hubFpsKey = "MISC FPS::FPS Boost"
            local fpsBoostToggle
            local function syncFPSBoostToHub(value)
                local desired = value == true
                if type(persistence) == "table" then persistence[hubFpsKey] = desired end
                globals.__NoirFPSRequestedBoost = desired
                local runtime = globals.__NoirFPSBoostRuntime
                local current
                if type(runtime) == "table" and type(runtime.Get) == "function" then
                    local ok, result = pcall(runtime.Get)
                    if ok then current = result end
                end
                if current == desired then return true end
                local previous = globals.__NoirFPSSyncing == true
                globals.__NoirFPSSyncing = true
                local control = globals.__NoirFPSBoostToggle
                local ok
                if type(control) == "function" then
                    ok = pcall(control, desired)
                elseif type(runtime) == "table" and type(runtime.Set) == "function" then
                    ok = pcall(runtime.Set, desired)
                end
                globals.__NoirFPSSyncing = previous
                return ok ~= false
            end
            if type(persistence) == "table" then
                local function migrate(label, oldLabel, defaultValue)
                    local key = "Noir Auto prediction profile::" .. label
                    if persistence[key] == nil then
                        local oldValue = persistence["SILENT AIM::" .. oldLabel]
                        persistence[key] = type(oldValue) == "boolean" and oldValue or defaultValue
                        return true
                    end
                    return false
                end
                local changed = false
                changed = migrate("Auto Prediction", "Omega Auto Revert", false) or changed
                changed = migrate("Adaptive Engine", "Omega Adaptive Engine", true) or changed
                changed = migrate("Lock Config", "Omega Lock Config", false) or changed
                changed = migrate("Upgrade Mode", "Omega Upgrade Mode", false) or changed
                changed = migrate("Monitor", "Omega Monitor", false) or changed
                if persistence[profileFpsKey] == nil then
                    local oldFPS = persistence[hubFpsKey]
                    persistence[profileFpsKey] = type(oldFPS) == "boolean" and oldFPS or false
                    changed = true
                end
                if type(persistence[profileFpsKey]) == "boolean"
                    and persistence[hubFpsKey] ~= persistence[profileFpsKey] then
                    persistence[hubFpsKey] = persistence[profileFpsKey]
                    changed = true
                end
                if changed and NoirPersistence and type(NoirPersistence.Save) == "function" then
                    pcall(NoirPersistence.Save)
                end
            end
            globals.__NoirSetPredictionFPSBoost = function(value)
                local desired = value == true
                if type(persistence) == "table" then
                    persistence[profileFpsKey] = desired
                    persistence[hubFpsKey] = desired
                end
                globals.__NoirFPSRequestedBoost = desired
                local changed = profileState.fpsBoost ~= desired
                profileState.fpsBoost = desired
                if changed and not profileState.initializing and type(fpsBoostToggle) == "function" then
                    local previous = globals.__NoirFPSSyncing == true
                    globals.__NoirFPSSyncing = true
                    pcall(fpsBoostToggle, desired)
                    globals.__NoirFPSSyncing = previous
                end
            end

            local predictionSection = tab:AddSection("Noir Auto prediction profile", "Ping-adaptive Silent Aim prediction")
            predictionSection:AddToggle("Auto Prediction", function(value)
                profileState.enabled = value == true
                if not profileState.initializing then
                    reconfigure(true)
                    notify(tr("Auto Prediction") .. ": " .. tr(profileState.enabled and "ON" or "OFF"), 2)
                end
            end)
            predictionSection:AddToggle("Adaptive Engine", function(value)
                local nextValue = value == true
                if profileState.adaptive ~= nextValue then
                    profileState.adaptive = nextValue
                    profileState.classicIndex = nil
                    profileState.smoothedPing = profileState.rawPing
                end
                if not profileState.initializing then
                    reconfigure(true)
                    notify(tr("Adaptive Engine") .. ": " .. tr(profileState.adaptive and "ON" or "OFF"), 2)
                end
            end)
            predictionSection:AddToggle("Lock Config", function(value)
                profileState.locked = value == true
                if not profileState.initializing then
                    reconfigure(not profileState.locked)
                    notify(tr("Config") .. ": " .. tr(profileState.locked and "LOCKED" or "UNLOCKED"), 2)
                end
            end)
            predictionSection:AddToggle("Upgrade Mode", function(value)
                profileState.upgrade = value == true
                if not profileState.initializing then
                    reconfigure(true)
                    notify(tr("Upgrade Mode") .. ": " .. tr(profileState.upgrade and "ON" or "OFF"), 2)
                end
            end)
            predictionSection:AddToggle("Monitor", function(value)
                profileState.monitor = value == true
                if not profileState.initializing then
                    if profileState.monitor then
                        samplePing(true)
                        createMonitor()
                    else
                        destroyMonitor()
                    end
                    refreshStatus()
                    syncWorker()
                end
            end)
            fpsBoostToggle = predictionSection:AddToggle("FPS Boost", function(value)
                profileState.fpsBoost = value == true
                if not profileState.initializing and globals.__NoirFPSSyncing ~= true then
                    syncFPSBoostToHub(profileState.fpsBoost)
                end
            end)
            predictionSection:AddButton("Print Telemetry", telemetry)
            statusControl = predictionSection:AddLabel("")
            predictionSection:AddLabel("Noir Auto updates gun prediction using ping. Turning it off stops updates and keeps the last values.")
            predictionSection:AddLabel("FPS Boost is shared with the hub's MISC FPS control.")

            profileState.initializing = false
            syncFPSBoostToHub(profileState.fpsBoost)
            if profileState.monitor then
                samplePing(true)
                createMonitor()
            end
            if profileState.enabled and not profileState.locked then applyProfile(true) end
            refreshStatus()
            syncWorker()

            globals.__NoirPredictionRuntime = {
                Stop = function()
                    if not profileState.alive then return end
                    profileState.alive = false
                    profileState.workerToken = nil
                    destroyMonitor()
                end,
                Sync = function()
                    if profileState.enabled and not profileState.locked then applyProfile(true)
                    else refreshStatus() end
                end,
            }
        end

        combatAim:AddLabel("GUN UTILITIES native Noir implementation")
        combatAim:AddParagraph("GUN TRIGGER BOT", "Shoots once when the centre cursor/crosshair points at the Murderer. Works with mobile Shift Lock; move off target and back to arm the next shot.")
        combatAim:AddToggle("Gun Trigger Bot", function(v) config.gunTriggerBot = v == true end)
        combatAim:AddToggle("Gun Trigger Bot Wall Check", function(v) config.gunTriggerBotWallCheck = v == true end)
        combatAim:AddToggle("Apply Prediction On Gun Trigger Bot", function(v) config.gunTriggerBotPrediction = v == true end)

        local combatGun=tab:AddSection("GUN", "Gun targeting controls")
            combatGun:AddToggle("Piercer Bullet", setPiercerBullet)
        combatGun:AddLabel("If a wall is between you and the target, the shot starts on their side of the wall. Turn this on with Silent Aim.")

        local combatKnife=tab:AddSection("KNIFE SILENT AIM", "Nearest player or Sheriff-only targeting")
        combatKnife:AddToggle("Knife Silent Aim", function(v)
            config.knifeEnabled=v==true
            if config.knifeEnabled then installHook() end
        end)
         
        local oldKnifeAuraKey = "KNIFE SILENT AIM::Knife Radius"
        local newKnifeAuraKey = "KNIFE SILENT AIM::Knife Throw Aura"
        if NoirPersistence.data.sliders[newKnifeAuraKey] == nil and NoirPersistence.data.sliders[oldKnifeAuraKey] ~= nil then
            NoirPersistence.data.sliders[newKnifeAuraKey] = NoirPersistence.data.sliders[oldKnifeAuraKey]
            NoirPersistence.Save()
        end
         
         
        local knifeAuraToggle = combatKnife:AddToggle("KnifeThrown Aura", function(v) config.knifeThrownAura=v==true end)
        if NoirPersistence.data.toggles["KNIFE SILENT AIM::KnifeThrown Aura"] == nil then
            knifeAuraToggle(true)
        end
        combatKnife:AddSlider("Knife Throw Aura", 1, 40, config.knifeRadius, function(v) config.knifeRadius = tonumber(v) or config.knifeRadius end)
        combatKnife:AddToggle("Knife Wall Check", function(v) config.knifeWallCheck=v==true end)
        combatKnife:AddToggle("Prioritize Sheriff", function(v)
            config.knifePrioritizeSheriff=v==true
        end)
        combatKnife:AddLabel("NATIVE KNIFE UTILITIES equipped Knife only")
        local function refreshKnifeUtilities()
            local runtime = NoirGenv().__NoirKnifeUtilityRuntime
            if type(runtime) == "table" and type(runtime.Refresh) == "function" then pcall(runtime.Refresh, runtime) end
        end
        local function knifeRuntimeCall(method)
            local runtime = NoirGenv().__NoirKnifeUtilityRuntime
            if type(runtime) == "table" and type(runtime[method]) == "function" then return runtime[method](runtime) end
            notify("Knife utilities are starting", 2)
            return nil
        end
        combatKnife:AddToggle("Instant Throw", function(v)
            config.knifeInstantThrow = v == true
            if config.knifeInstantThrow then installHook() end
        end)
        combatKnife:AddToggle("Fast Throw", function(v)
            config.knifeFastThrow = v == true
            if config.knifeFastThrow then installHook() end
        end)
        combatKnife:AddToggle("Auto Kill Everyone", function(v) config.knifeAutoKillEveryone = v == true end)
        combatKnife:AddToggle("Auto Kill Sheriff", function(v) config.knifeAutoKillSheriff = v == true end)
        combatKnife:AddButton("Kill Everyone", function() knifeRuntimeCall("KillEveryone") end)
        combatKnife:AddButton("Kill Sheriff", function() knifeRuntimeCall("KillSheriff") end)
        combatKnife:AddToggle("Enable Kill Sheriff Bindable Button", function(v) config.knifeSheriffBind = v == true; refreshKnifeUtilities() end)
        local function knifePlayerChoices()
            local values = { "N/A" }
            for _, player in ipairs(getPlayers()) do if player ~= LocalPlayer then values[#values + 1] = player.Name end end
            table.sort(values, function(a, b) if a == "N/A" then return true elseif b == "N/A" then return false end return string.lower(a) < string.lower(b) end)
            return values
        end
        local selectedKnifePlayer = combatKnife:AddDropdown("Kill Player", knifePlayerChoices(), function(v) config.knifeKillPlayer = tostring(v or "N/A") end)
        combatKnife:AddButton("Kill Player", function() knifeRuntimeCall("KillSelected") end)
        combatKnife:AddButton("Refresh Kill Player List", function() selectedKnifePlayer:Refresh(knifePlayerChoices(), config.knifeKillPlayer) end)
        local function refreshKnifePlayerList()
            if selectedKnifePlayer and selectedKnifePlayer.Refresh then
                selectedKnifePlayer:Refresh(knifePlayerChoices(), config.knifeKillPlayer)
            end
        end
        Players.PlayerAdded:Connect(function() task.delay(.15, refreshKnifePlayerList) end)
        Players.PlayerRemoving:Connect(function() task.delay(.15, refreshKnifePlayerList) end)

        local function addPrediction(section,profile,prefix)
            local function addToggle(key,label)
                local control=section:AddToggle(label,function(v) profile[key]=v==true end)
                noirMirrorControls[prefix..key]=control
                revertToggleStates[prefix..key]=profile[key]==true
            end
            local function addSlider(key,label,min,max)
                local control=section:AddSlider(label,min,max,tonumber(profile[key]) or min,function(v) profile[key]=tonumber(v) or profile[key] end)
                noirMirrorControls[prefix..key]=control
                if key=="manualPingMs" then noirMirrorControls[prefix=="knife." and "knifeManualPingMs" or "manualPingMs"]=control end
            end
            addToggle("prioritizePing","Prioritize Your Ping")
            addToggle("predictJump","Predict Jump")
            addToggle("predictLag","Predict Lag")
            addSlider("maxSimulationMs","Prediction Max Simulation",20,300)
            addSlider("predictionIntervalMs","Prediction Interval",1,100)
            addSlider("manualPingMs","Prediction Ping",10,1000)
            addSlider("offsetX","X Position Offset",-100,100)
            addSlider("offsetY","Y Position Offset",-100,100)
            addSlider("offsetZ","Z Position Offset",-100,100)
            addSlider("horizontalMultiplier","Horizontal Multiplier",0,400)
            addSlider("verticalMultiplier","Vertical Multiplier",0,400)
        end

        local pistolPrediction=tab:AddSection("PISTOL PREDICTION", "Independent server-shot prediction")
        addPrediction(pistolPrediction,config,"pistol.")
        local knifePrediction=tab:AddSection("KNIFE PREDICTION", "Independent KnifeThrown prediction")
        addPrediction(knifePrediction,config.knifeAim,"knife.")

        local profileKeys={"adaptive","fixedLead","extraLead","prioritizePing","predictJump","predictLag","maxSimulationMs","predictionIntervalMs","manualPingMs","offsetX","offsetY","offsetZ","horizontalMultiplier","verticalMultiplier"}
        local function profileSnapshot(profile)
            local data={}
            for _,key in ipairs(profileKeys) do data[key]=profile[key] end
            return data
        end
        local function applyProfile(profile,data)
            if typeof(data)~="table" then return false end
            for _,key in ipairs(profileKeys) do
                if typeof(data[key])==typeof(profile[key]) then profile[key]=data[key] end
            end
            if type(syncRevertControls)=="function" then syncRevertControls() end
            return true
        end
        local function profilePresetNames(kind)
            local names={"default"}
            if type(listfiles)=="function" then
                ensurePresetFolder()
                local ok,files=pcall(listfiles,PRESET_FOLDER)
                if ok and typeof(files)=="table" then
                    local suffix="_"..string.lower(kind).."%.preset$"
                    for _,file in ipairs(files) do
                        local base=tostring(file):gsub("\\","/"):match("([^/]+)"..suffix)
                        if base and not table.find(names,base) then names[#names+1]=base end
                    end
                end
            end
            table.sort(names)
            return names
        end
        local function addProfileConfig(title,kind,profile)
            local section=tab:AddSection(title,"Independent "..kind.." preset storage")
            local selected="default"
            section:AddDropdown("Your Presets",profilePresetNames(kind),function(v) selected=cleanPresetName(v) end)
            section:AddTextBox("Preset Name",function(v) selected=cleanPresetName(v) end)
            section:AddButton("Save "..kind.." Preset",function()
                if type(writefile)~="function" then notify("Executor does not support writefile",4) return end
                ensurePresetFolder()
                local payload={version=4,kind=string.lower(kind),profile=profileSnapshot(profile)}
                local ok,encoded=pcall(function() return HttpService:JSONEncode(payload) end)
                local path=PRESET_FOLDER.."/"..selected.."_"..string.lower(kind)..".preset"
                if ok and pcall(writefile,path,xorPreset(encoded)) then notify(kind.." preset saved: "..selected,3) else notify(kind.." preset save failed",4) end
            end)
            section:AddButton("Load "..kind.." Preset",function()
                if type(readfile)~="function" then notify("Executor does not support readfile",4) return end
                local path=PRESET_FOLDER.."/"..selected.."_"..string.lower(kind)..".preset"
                local ok,data=pcall(function() return HttpService:JSONDecode(xorPreset(readfile(path))) end)
                if ok and typeof(data)=="table" and data.kind==string.lower(kind) and applyProfile(profile,data.profile) then notify(kind.." preset loaded: "..selected,3) else notify(kind.." preset not found or invalid",4) end
            end)
        end
        addProfileConfig("PISTOL NOIR CONFIG","Pistol",config)
        addProfileConfig("KNIFE NOIR CONFIG","Knife",config.knifeAim)

        syncRevertControls=function()
            for _,entry in ipairs({
                {"pistol.prioritizePing",config.prioritizePing},{"pistol.predictJump",config.predictJump},{"pistol.predictLag",config.predictLag},
                {"knife.prioritizePing",config.knifeAim.prioritizePing},{"knife.predictJump",config.knifeAim.predictJump},{"knife.predictLag",config.knifeAim.predictLag}
            }) do
                local control=noirMirrorControls[entry[1]]
                if type(control)=="function" then pcall(control,entry[2]) end
            end
            for _,entry in ipairs({
                {"pistol.maxSimulationMs",config.maxSimulationMs},{"pistol.predictionIntervalMs",config.predictionIntervalMs},{"pistol.manualPingMs",config.manualPingMs},
                {"pistol.offsetX",config.offsetX},{"pistol.offsetY",config.offsetY},{"pistol.offsetZ",config.offsetZ},{"pistol.horizontalMultiplier",config.horizontalMultiplier},{"pistol.verticalMultiplier",config.verticalMultiplier},
                {"knife.maxSimulationMs",config.knifeAim.maxSimulationMs},{"knife.predictionIntervalMs",config.knifeAim.predictionIntervalMs},{"knife.manualPingMs",config.knifeAim.manualPingMs},
                {"knife.offsetX",config.knifeAim.offsetX},{"knife.offsetY",config.knifeAim.offsetY},{"knife.offsetZ",config.knifeAim.offsetZ},{"knife.horizontalMultiplier",config.knifeAim.horizontalMultiplier},{"knife.verticalMultiplier",config.knifeAim.verticalMultiplier}
            }) do
                local control=noirMirrorControls[entry[1]]
                if type(control)=="table" and type(control.SetValue)=="function" then pcall(control.SetValue,control,entry[2]) end
            end
        local predictionRuntime = NoirGenv().__NoirPredictionRuntime
        if type(predictionRuntime) == "table" and type(predictionRuntime.Sync) == "function" then predictionRuntime.Sync() end
        end
        syncRevertControls()
    end
    buildCombatControls()
end

local remoteConnections = {}
function connectRemote(name, handler)
    local wanted = string.lower(tostring(name))
    local first
    for _, remote in ipairs(ReplicatedStorage:GetDescendants()) do
        if string.lower(remote.Name) == wanted then
            if remote:IsA("RemoteEvent") then
                first = first or remote
                table.insert(remoteConnections, remote.OnClientEvent:Connect(function(...) pcall(handler, ...) end))
            elseif remote:IsA("BindableEvent") then
                first = first or remote
                table.insert(remoteConnections, remote.Event:Connect(function(...) pcall(handler, ...) end))
            end
        end
    end
    return first
end

connectRemote("PlayerDataChanged", function(first, second)
    if typeof(second) == "table" and typeof(first) == "Instance" and first:IsA("Player") then
        consumeData({ [first.Name] = second }, false)
    else
        consumeData(first, false)
    end
end)
connectRemote("RoundStart", function(timerValue, roundData)
    beginRoundTimer(timerValue)
    murderer, sheriff, hero = nil, nil, nil
    table.clear(roleCache); table.clear(announcedRoles)
    if typeof(roundData) == "table" then consumeData(roundData, true) end
    refreshTarget(true)
end)
local function finishRound()
    resetRoundTimer()
    murderer, sheriff, hero = nil, nil, nil
    table.clear(roleCache); table.clear(announcedRoles)
end
connectRemote("RoundEndFade", finishRound)
connectRemote("RoundEnd", finishRound)
connectRemote("RoleSelect", function() task.spawn(refreshTarget) end)
connectRemote("ShowRoleSelect", function() task.spawn(refreshTarget) end)
connectRemote("ShowRoleSelectNew", function() task.spawn(refreshTarget) end)
