-- Better-ODH ports satellite: Bomb Jump extras (into the Bomb Jump+ section)
-- and Backshots (into the Trolling page). Isolated chunk, like Noclip/Fly.
do
    local __noirTrollSource = "-- Better-ODH ports for Noir: Bomb Jump extras (into the existing Bomb Jump+\n-- section) and the Backshots feature (into a new TROLL page). Isolated chunk.\nlocal M = NoirGenv().__NoirMovementContext\nif type(M) ~= \"table\" or not M.tab or not M.persistence then\n    warn(\"[Noir Troll] context unavailable.\")\n    return\nend\n\nlocal Players, UIS, RunService, Workspace = M.players, M.uis, M.runService, M.workspace\nlocal LocalPlayer, Persistence = M.localPlayer, M.persistence\nlocal TweenService = game:GetService(\"TweenService\")\n\nlocal BORDER = Color3.fromRGB(62, 66, 74)\nlocal ACCENT2 = Color3.fromRGB(226, 230, 238)\nlocal DIM = Color3.fromRGB(122, 127, 138)\nlocal TEXT = Color3.fromRGB(245, 246, 248)\n\nlocal function New(class, props)\n    local inst = Instance.new(class)\n    for key, value in pairs(props) do inst[key] = value end\n    return inst\nend\nlocal function corner(inst, radius)\n    local c = Instance.new(\"UICorner\")\n    c.CornerRadius = UDim.new(0, radius or 12)\n    c.Parent = inst\n    return c\nend\nlocal function strokeOf(inst, color, trans, thick)\n    local s = Instance.new(\"UIStroke\")\n    s.Color = color\n    s.Transparency = trans or 0\n    s.Thickness = thick or 2\n    s.ApplyStrokeMode = Enum.ApplyStrokeMode.Border\n    s.Parent = inst\n    return s\nend\nlocal function monoGradient(strokeInst)\n    local g = Instance.new(\"UIGradient\")\n    g.Color = ColorSequence.new({\n        ColorSequenceKeypoint.new(0, Color3.fromRGB(35, 35, 40)),\n        ColorSequenceKeypoint.new(.22, Color3.fromRGB(250, 250, 252)),\n        ColorSequenceKeypoint.new(.48, Color3.fromRGB(70, 70, 78)),\n        ColorSequenceKeypoint.new(.72, Color3.fromRGB(255, 255, 255)),\n        ColorSequenceKeypoint.new(1, Color3.fromRGB(45, 45, 52)),\n    })\n    g.Parent = strokeInst\n    return g\nend\nlocal function makeDraggable(button, key, conns)\n    local dragging, moved, dragStart, startPosition, dragInput = false, false, nil, nil, nil\n    conns[#conns + 1] = button.InputBegan:Connect(function(input)\n        if not M.isPrimaryPress(input) then return end\n        dragging, moved, dragStart, startPosition = true, false, input.Position, button.Position\n    end)\n    conns[#conns + 1] = button.InputChanged:Connect(function(input)\n        if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then dragInput = input end\n    end)\n    conns[#conns + 1] = UIS.InputChanged:Connect(function(input)\n        if not dragging or input ~= dragInput then return end\n        local delta = input.Position - dragStart\n        if delta.Magnitude > 7 then moved = true end\n        button.Position = UDim2.new(startPosition.X.Scale, startPosition.X.Offset + delta.X, startPosition.Y.Scale, startPosition.Y.Offset + delta.Y)\n    end)\n    conns[#conns + 1] = UIS.InputEnded:Connect(function(input)\n        if not dragging or not M.isPrimaryPress(input) then return end\n        dragging = false\n        Persistence.SetPosition(key, button.Position)\n    end)\n    return function() return moved end\nend\n\n-- ================================================================\n-- BOMB JUMP EXTRAS (Better ODH port) -> existing Bomb Jump+ section\n-- ================================================================\ndo\n    local bjp = NoirGenv().__NoirBJPSection\n    if type(bjp) == \"table\" then\n        local toyEvent = { InvokeServer = function(_, ...)\n            local storage = game:GetService(\"ReplicatedStorage\")\n            local remotes = storage and storage:FindFirstChild(\"Remotes\")\n            local extras = remotes and remotes:FindFirstChild(\"Extras\")\n            local remote = extras and extras:FindFirstChild(\"ReplicateToy\")\n            if not remote then return nil end\n            return remote:InvokeServer(...)\n        end }\n\n        local bj = {\n            useMode = \"Toggle To Use Bomb\", bombType = \"Bomb\", noGuiTimer = false,\n            waiting = false, size = 220, show = false,\n            gui = nil, frame = nil, button = nil, stroke = nil, conns = {},\n        }\n        local function toolName()\n            return bj.bombType == \"Gold Bomb\" and \"GoldBomb\" or \"FakeBomb\"\n        end\n        local DELAY = 0.1\n\n        local function executeBombJump(isToggleMode)\n            if bj.waiting then return end\n            local character = LocalPlayer.Character\n            if not character then return end\n            local humanoid = character:FindFirstChildOfClass(\"Humanoid\")\n            local root = character:FindFirstChild(\"HumanoidRootPart\")\n            if not humanoid or not root then return end\n            bj.waiting = true\n            task.spawn(function()\n                local name = toolName()\n                local backpack = LocalPlayer:FindFirstChild(\"Backpack\")\n                local tool = character:FindFirstChild(name) or (backpack and backpack:FindFirstChild(name))\n                if isToggleMode then\n                    humanoid:ChangeState(Enum.HumanoidStateType.Jumping)\n                    humanoid.Jump = true\n                    task.wait(DELAY)\n                    if tool then\n                        if tool.Parent == backpack then pcall(function() humanoid:EquipTool(tool) end) end\n                        task.wait(DELAY)\n                        pcall(function() toyEvent:InvokeServer(name) end)\n                        pcall(function() tool:Activate() end)\n                        pcall(function()\n                            local vu = game:GetService(\"VirtualUser\")\n                            vu:Button1Down(Vector2.zero)\n                            vu:Button1Up(Vector2.zero)\n                        end)\n                        task.wait(DELAY)\n                    end\n                    humanoid:ChangeState(Enum.HumanoidStateType.Jumping)\n                    humanoid.Jump = true\n                    task.wait(DELAY)\n                    if tool and tool.Parent == character then\n                        pcall(function() humanoid:UnequipTools() end)\n                        if tool.Parent == character and backpack then pcall(function() tool.Parent = backpack end) end\n                    end\n                else\n                    if not tool then bj.waiting = false; return end\n                    if tool.Parent == backpack then pcall(function() humanoid:EquipTool(tool) end) end\n                    task.wait(DELAY)\n                    pcall(function() toyEvent:InvokeServer(name) end)\n                    pcall(function() tool:Activate() end)\n                    pcall(function()\n                        local vu = game:GetService(\"VirtualUser\")\n                        vu:Button1Down(Vector2.zero)\n                        vu:Button1Up(Vector2.zero)\n                    end)\n                    humanoid:ChangeState(Enum.HumanoidStateType.Jumping)\n                    humanoid.Jump = true\n                    task.wait(DELAY)\n                    if tool.Parent == character then\n                        pcall(function() humanoid:UnequipTools() end)\n                        if tool.Parent == character and backpack then pcall(function() tool.Parent = backpack end) end\n                    end\n                end\n                if bj.button and bj.button.Parent then\n                    bj.button.Text = \"Bomb Jump (OFF)\"\n                    if bj.stroke then bj.stroke.Color = Color3.fromRGB(255, 255, 255) end\n                end\n                task.delay(1.2, function()\n                    bj.waiting = false\n                    if bj.button and bj.button.Parent then\n                        bj.button.Text = bj.useMode == \"Toggle To Use Bomb\" and \"Bomb Jump (OFF)\" or \"Bomb Jump\"\n                    end\n                end)\n            end)\n        end\n\n        local function paintIdle()\n            if not bj.button then return end\n            bj.button.Text = bj.useMode == \"Toggle To Use Bomb\" and \"Bomb Jump (OFF)\" or \"Bomb Jump\"\n            bj.button.TextColor3 = TEXT\n            if bj.stroke then bj.stroke.Color = Color3.fromRGB(255, 255, 255) end\n        end\n\n        local function buildBombGui()\n            if bj.gui and bj.gui.Parent then return end\n            local parent = M.guiParent\n            if typeof(parent) ~= \"Instance\" then parent = LocalPlayer:WaitForChild(\"PlayerGui\") end\n            local gui = New(\"ScreenGui\", { Parent = parent, Name = \"NoirBombJumpToggle\", ResetOnSpawn = false, IgnoreGuiInset = true, DisplayOrder = 86 })\n            local frame = New(\"Frame\", { Parent = gui, Name = \"BombFrame\", AnchorPoint = Vector2.new(.5, .5),\n                Position = Persistence.GetPosition(\"noir_bomb_jump_v1\", UDim2.new(.72, 0, .62, 0)),\n                Size = UDim2.fromOffset(bj.size, math.floor(bj.size * (100 / 220))), BackgroundTransparency = 1 })\n            local button = New(\"TextButton\", { Parent = frame, Size = UDim2.fromScale(1, 1),\n                BackgroundColor3 = Color3.fromRGB(8, 8, 10), BackgroundTransparency = .35, Text = \"\", AutoButtonColor = false,\n                Font = Enum.Font.GothamBold, TextColor3 = TEXT, TextSize = math.max(12, math.floor(bj.size / 12)), ZIndex = 6 })\n            corner(button, 16)\n            local st = strokeOf(button, Color3.fromRGB(255, 255, 255), 0, 2)\n            monoGradient(st)\n            bj.gui, bj.frame, bj.button, bj.stroke = gui, frame, button, st\n            paintIdle()\n            local wasMoved = makeDraggable(button, \"noir_bomb_jump_v1\", bj.conns)\n            bj.conns[#bj.conns + 1] = button.MouseButton1Click:Connect(function()\n                if wasMoved() then return end\n                if bj.useMode == \"Toggle To Use Bomb\" then\n                    if bj.waiting then return end\n                    bj.button.Text = \"Ready\"\n                    bj.button.TextColor3 = Color3.fromRGB(50, 255, 50)\n                    if bj.stroke then bj.stroke.Color = Color3.fromRGB(50, 200, 50) end\n                    executeBombJump(true)\n                else\n                    executeBombJump(false)\n                end\n            end)\n        end\n\n        pcall(function()\n            bjp:AddToggle(\"Show Bomb Jump Button\", function(on)\n                bj.show = on == true\n                if bj.show then\n                    buildBombGui()\n                    if bj.gui then bj.gui.Enabled = true end\n                elseif bj.gui then\n                    bj.gui.Enabled = false\n                end\n            end)\n        end)\n        pcall(function()\n            bjp:AddDropdown(\"Choose Bomb Type\", { \"Bomb\", \"Gold Bomb\" }, function(sel)\n                bj.bombType = sel or bj.bombType\n            end)\n        end)\n        pcall(function()\n            bjp:AddDropdown(\"Bomb Usage Mode\", { \"Toggle To Use Bomb\", \"Click To Use Bomb\" }, function(sel)\n                bj.useMode = sel or bj.useMode\n                paintIdle()\n            end)\n        end)\n        pcall(function()\n            bjp:AddToggle(\"No GUI Timer ( Not Recommended )\", function(on)\n                bj.noGuiTimer = on == true\n                if bj.noGuiTimer then paintIdle() end\n            end)\n        end)\n        pcall(function()\n            bjp:AddKeybind(\"Bomb Jump Keybind\", \"B\", function()\n                if bj.useMode == \"Toggle To Use Bomb\" then\n                    if bj.button and bj.button.Parent then\n                        bj.button.Text = \"Ready\"\n                        bj.button.TextColor3 = Color3.fromRGB(50, 255, 50)\n                        if bj.stroke then bj.stroke.Color = Color3.fromRGB(50, 200, 50) end\n                    end\n                    executeBombJump(true)\n                else\n                    executeBombJump(false)\n                end\n            end)\n        end)\n        pcall(function()\n            bjp:AddSlider(\"Bomb Jump GUI Size\", 50, 300, bj.size, function(v)\n                bj.size = math.clamp(tonumber(v) or bj.size, 50, 300)\n                if bj.frame then\n                    bj.frame.Size = UDim2.fromOffset(bj.size, math.floor(bj.size * (100 / 220)))\n                end\n                if bj.button then bj.button.TextSize = math.max(12, math.floor(bj.size / 12)) end\n            end)\n        end)\n        pcall(function() bjp:AddLabel(\"Bomb Jump ported from Better ODH: jump-equip-use-jump sequence with cooldown guard.\") end)\n    end\nend\n\n-- ================================================================\n-- BACKSHOTS (Better ODH port) -> TROLL page\n-- ================================================================\ndo\n    local section = M.tab:AddSection(\"TROLL \\u{2022} BACKSHOTS\", \"Movement troll ported from Better ODH\")\n    local bs = {\n        active = false, show = false, speed = 0.25, maxDistance = 1,\n        gui = nil, button = nil, connection = nil, centerPos = nil, lastRootPos = nil,\n        walkDir = 1, landDelayTick = 0, wasInAir = false, conns = {},\n    }\n    local Camera = Workspace.CurrentCamera\n\n    local function setNoPlayerCollision(enabled)\n        local character = LocalPlayer.Character\n        if not character then return end\n        for _, other in ipairs(Players:GetPlayers()) do\n            if other ~= LocalPlayer and other.Character then\n                for _, part in ipairs(other.Character:GetDescendants()) do\n                    if part:IsA(\"BasePart\") then part.CanCollide = not enabled end\n                end\n            end\n        end\n    end\n\n    local function stopBackshots()\n        bs.active = false\n        if bs.button then\n            bs.button.Text = \"backshots: OFF\"\n            bs.button.BackgroundColor3 = Color3.fromRGB(40, 40, 40)\n        end\n        if bs.connection then bs.connection:Disconnect(); bs.connection = nil end\n        setNoPlayerCollision(false)\n        local character = LocalPlayer.Character\n        if character then\n            local humanoid = character:FindFirstChildOfClass(\"Humanoid\")\n            if humanoid then\n                humanoid.AutoRotate = true\n                humanoid:Move(Vector3.zero, true)\n            end\n        end\n        bs.centerPos, bs.lastRootPos = nil, nil\n    end\n\n    local function startBackshots()\n        local character = LocalPlayer.Character\n        local root = character and character:FindFirstChild(\"HumanoidRootPart\")\n        local humanoid = character and character:FindFirstChildOfClass(\"Humanoid\")\n        bs.active = true\n        if bs.button then\n            bs.button.Text = \"backshots: ON\"\n            bs.button.BackgroundColor3 = Color3.fromRGB(0, 170, 0)\n        end\n        if not (root and humanoid) then return end\n        bs.centerPos = root.Position\n        bs.lastRootPos = root.Position\n        bs.walkDir = 1\n        humanoid.AutoRotate = false\n        bs.landDelayTick = 0\n        bs.wasInAir = false\n        bs.connection = RunService.RenderStepped:Connect(function()\n            if not character or not character.Parent or humanoid.Health <= 0 then return end\n            setNoPlayerCollision(true)\n            local currentPos = root.Position\n            if bs.lastRootPos and (currentPos - bs.lastRootPos).Magnitude > 25 then bs.centerPos = currentPos end\n            bs.lastRootPos = currentPos\n            local camera = Workspace.CurrentCamera\n            local lookVector = camera and camera.CFrame.LookVector or Vector3.new(0, 0, -1)\n            local flatLook = Vector3.new(lookVector.X, 0, lookVector.Z)\n            if flatLook.Magnitude > 0 then\n                flatLook = flatLook.Unit\n            else\n                local rl = root.CFrame.LookVector\n                flatLook = Vector3.new(rl.X, 0, rl.Z).Unit\n            end\n            local state = humanoid:GetState()\n            local inAir = state == Enum.HumanoidStateType.Freefall or state == Enum.HumanoidStateType.Jumping or state == Enum.HumanoidStateType.FallingDown\n            if inAir then\n                bs.wasInAir = true\n                bs.centerPos = root.Position\n                bs.walkDir = 1\n                bs.landDelayTick = tick() + 0.1\n            elseif bs.wasInAir and not inAir then\n                bs.wasInAir = false\n            end\n            if humanoid.MoveDirection.Magnitude > 0 then\n                bs.centerPos = root.Position\n                bs.walkDir = 1\n            end\n            if tick() < bs.landDelayTick then\n                bs.centerPos = root.Position\n                return\n            end\n            local lockedLookCFrame = CFrame.lookAt(bs.centerPos, bs.centerPos + flatLook)\n            local displacement = (currentPos - bs.centerPos):Dot(flatLook)\n            if displacement >= bs.maxDistance then\n                bs.walkDir = -1\n            elseif displacement <= -bs.maxDistance then\n                bs.walkDir = 1\n            end\n            local targetPosition = lockedLookCFrame.Position + (bs.centerPos - lockedLookCFrame.Position) + (flatLook * displacement)\n            local params = RaycastParams.new()\n            params.FilterType = Enum.RaycastFilterType.Exclude\n            params.FilterDescendantsInstances = { character }\n            local hit = Workspace:Raycast(bs.centerPos + Vector3.new(0, 2, 0), (targetPosition - bs.centerPos), params)\n            if hit then targetPosition = hit.Position - (flatLook * 0.2) end\n            local goalCFrame = lockedLookCFrame + (targetPosition - bs.centerPos)\n            root.CFrame = root.CFrame:Lerp(goalCFrame, bs.speed)\n            humanoid:Move(flatLook * bs.walkDir, false)\n        end)\n    end\n\n    local function toggleBackshots(state)\n        if state then startBackshots() else stopBackshots() end\n    end\n\n    local function buildBackshotsGui()\n        if bs.gui and bs.gui.Parent then return end\n        local parent = M.guiParent\n        if typeof(parent) ~= \"Instance\" then parent = LocalPlayer:WaitForChild(\"PlayerGui\") end\n        local gui = New(\"ScreenGui\", { Parent = parent, Name = \"NoirBackshotsToggle\", ResetOnSpawn = false, IgnoreGuiInset = true, DisplayOrder = 88 })\n        local button = New(\"TextButton\", { Parent = gui, Name = \"backshots\",\n            Position = Persistence.GetPosition(\"noir_backshots_v1\", UDim2.new(.1, 0, .1, 0)),\n            Size = UDim2.fromOffset(120, 50), BackgroundColor3 = Color3.fromRGB(40, 40, 40),\n            TextColor3 = Color3.fromRGB(255, 255, 255), TextSize = 14, Font = Enum.Font.GothamBold, Text = \"backshots: OFF\", AutoButtonColor = false, ZIndex = 7 })\n        corner(button, 12)\n        strokeOf(button, BORDER, .2, 1.5)\n        bs.gui, bs.button = gui, button\n        local wasMoved = makeDraggable(button, \"noir_backshots_v1\", bs.conns)\n        bs.conns[#bs.conns + 1] = button.MouseButton1Click:Connect(function()\n            if wasMoved() then return end\n            toggleBackshots(not bs.active)\n        end)\n    end\n\n    LocalPlayer.CharacterAdded:Connect(function()\n        if bs.active then toggleBackshots(false) end\n    end)\n\n    pcall(function()\n        section:AddToggle(\"Show Backshots Button\", function(on)\n            bs.show = on == true\n            if bs.show then\n                buildBackshotsGui()\n                if bs.gui then bs.gui.Enabled = true end\n            elseif bs.gui then\n                bs.gui.Enabled = false\n                if bs.active then toggleBackshots(false) end\n            end\n        end)\n    end)\n    pcall(function()\n        section:AddKeybind(\"Backshots Keybind\", \"B\", function()\n            if bs.gui and bs.gui.Enabled then toggleBackshots(not bs.active) end\n        end)\n    end)\n    pcall(function()\n        section:AddSlider(\"Backshots Speed\", 1, 100, 25, function(v) bs.speed = (tonumber(v) or 25) / 100 end)\n    end)\n    pcall(function()\n        section:AddSlider(\"Backshots Distance\", 1, 50, 10, function(v) bs.maxDistance = (tonumber(v) or 10) / 10 end)\n    end)\n    pcall(function()\n        section:AddSlider(\"Backshots GUI Size\", 50, 250, 120, function(v)\n            local numV = tonumber(v) or 120\n            if bs.button then\n                bs.button.Size = UDim2.fromOffset(numV, math.floor(numV * (50 / 120)))\n                bs.button.TextSize = math.clamp(math.floor(numV / 8), 10, 24)\n            end\n        end)\n    end)\n    pcall(function() section:AddLabel(\"Backshots ported from Better ODH: camera-locked backward shuffle troll.\") end)\nend\n\n-- ================================================================\n-- JERK R15 (community recreation of the FE R15 animation glitch)\n-- ================================================================\ndo\n    local section = M.tab:AddSection(\"TROLL \\u{2022} JERK R15\", \"R15 animation glitch troll\")\n    local jk = { active = false, interval = 0.1, track = nil, timer = 0, hi = false, conn = nil,\n        gui = nil, button = nil, stroke = nil, size = 64, conns = {} }\n    local toggleJerk\n\n    local function paintJerk()\n        if not jk.button or not jk.button.Parent then return end\n        jk.button.TextColor3 = jk.active and Color3.fromRGB(120, 255, 140) or TEXT\n        if jk.stroke then\n            jk.stroke.Color = jk.active and Color3.fromRGB(80, 220, 110) or Color3.fromRGB(255, 255, 255)\n        end\n    end\n\n    local function stopJerk()\n        jk.active = false\n        if jk.conn then jk.conn:Disconnect(); jk.conn = nil end\n        if jk.track then pcall(function() jk.track:Stop() end); jk.track = nil end\n        jk.timer, jk.hi = 0, false\n        paintJerk()\n    end\n\n    local function buildJerkGui()\n        if jk.gui and jk.gui.Parent then return end\n        local parent = M.guiParent\n        if typeof(parent) ~= \"Instance\" then parent = LocalPlayer:WaitForChild(\"PlayerGui\") end\n        local gui = New(\"ScreenGui\", { Parent = parent, Name = \"NoirJerkToggle\", ResetOnSpawn = false, IgnoreGuiInset = true, DisplayOrder = 87 })\n        local button = New(\"TextButton\", { Parent = gui, Name = \"Jerk\", AnchorPoint = Vector2.new(.5, .5),\n            Position = Persistence.GetPosition(\"noir_jerk_v1\", UDim2.new(.86, 0, .5, 0)),\n            Size = UDim2.fromOffset(jk.size, jk.size), BackgroundColor3 = Color3.fromRGB(7, 8, 11), BackgroundTransparency = .35,\n            Text = \"JERK\", Font = Enum.Font.GothamBold, TextColor3 = TEXT, TextSize = math.max(9, math.floor(jk.size / 6)), AutoButtonColor = false, ZIndex = 8 })\n        corner(button, 999)\n        local st = strokeOf(button, Color3.fromRGB(255, 255, 255), 0, 2)\n        monoGradient(st)\n        jk.gui, jk.button, jk.stroke = gui, button, st\n        paintJerk()\n        local wasMoved = makeDraggable(button, \"noir_jerk_v1\", jk.conns)\n        jk.conns[#jk.conns + 1] = button.MouseButton1Click:Connect(function()\n            if wasMoved() then return end\n            toggleJerk(not jk.active)\n        end)\n    end\n\n    local function startJerk()\n        local character = LocalPlayer.Character\n        local humanoid = character and character:FindFirstChildOfClass(\"Humanoid\")\n        if not humanoid then return end\n        if humanoid.RigType ~= Enum.HumanoidRigType.R15 then\n            warn(\"[Noir Troll] Jerk R15 needs an R15 rig.\")\n            return\n        end\n        local animation = Instance.new(\"Animation\")\n        animation.AnimationId = \"rbxassetid://698251653\"\n        local ok, track = pcall(function() return humanoid:LoadAnimation(animation) end)\n        if not ok or not track then return end\n        jk.track, jk.timer, jk.hi = track, 0, false\n        track.Looped = true\n        track:Play()\n        jk.active = true\n        jk.conn = RunService.Heartbeat:Connect(function(deltaTime)\n            if not jk.active or not jk.track then return end\n            if not jk.track.IsPlaying then pcall(function() jk.track:Play() end) end\n            jk.timer = jk.timer + deltaTime\n            if jk.timer >= jk.interval then\n                jk.timer = 0\n                jk.hi = not jk.hi\n                pcall(function() jk.track.TimePosition = jk.hi and 0.65 or 0.6 end)\n            end\n        end)\n    end\n\n    toggleJerk = function(state)\n        if state then startJerk() else stopJerk() end\n        paintJerk()\n    end\n\n    LocalPlayer.CharacterAdded:Connect(function()\n        if jk.active then toggleJerk(false) end\n    end)\n\n    pcall(function()\n        section:AddToggle(\"Show Jerk Button\", function(on)\n            if on == true then\n                buildJerkGui()\n                if jk.gui then jk.gui.Enabled = true end\n            elseif jk.gui then\n                jk.gui.Enabled = false\n                if jk.active then toggleJerk(false) end\n            end\n        end)\n    end)\n    pcall(function()\n        section:AddSlider(\"Jerk Button Size\", 40, 150, 64, function(v)\n            jk.size = math.clamp(tonumber(v) or 64, 40, 150)\n            if jk.button then\n                jk.button.Size = UDim2.fromOffset(jk.size, jk.size)\n                jk.button.TextSize = math.max(9, math.floor(jk.size / 6))\n            end\n        end)\n    end)\n    pcall(function()\n        section:AddToggle(\"Enable Jerk R15\", function(on) toggleJerk(on == true) end)\n    end)\n    pcall(function()\n        section:AddSlider(\"Jerk Speed (higher = faster)\", 1, 100, 10, function(v)\n            local speed = math.clamp(tonumber(v) or 10, 1, 100)\n            jk.interval = 1 / speed\n        end)\n    end)\n    pcall(function()\n        section:AddKeybind(\"Jerk R15 Keybind\", \"J\", function() toggleJerk(not jk.active) end)\n    end)\n    pcall(function() section:AddLabel(\"Requires an R15 rig. Reapplies if the track stops; turns off on respawn.\") end)\nend\n\n-- ================================================================\n-- BANG (classic FE bang troll: looped animation while pinned to\n-- the target player's CFrame; based on the public bang scripts)\n-- ================================================================\ndo\n    local section = M.tab:AddSection(\"TROLL \\u{2022} BANG\", \"Classic bang troll: stick to a player with a looping animation\")\n    local bg = { target = nil, active = false, speed = 10, track = nil, conn = nil, phase = 0 }\n\n    local function stopBang()\n        bg.active = false\n        if bg.conn then bg.conn:Disconnect(); bg.conn = nil end\n        if bg.track then pcall(function() bg.track:Stop() end); bg.track = nil end\n    end\n\n    local function targetPlayer()\n        if not bg.target or bg.target == \"None\" then return nil end\n        return Players:FindFirstChild(bg.target)\n    end\n\n    local function startBang()\n        local character = LocalPlayer.Character\n        local humanoid = character and character:FindFirstChildOfClass(\"Humanoid\")\n        local root = character and character:FindFirstChild(\"HumanoidRootPart\")\n        if not (humanoid and root) then return false end\n        local animation = Instance.new(\"Animation\")\n        animation.AnimationId = \"rbxassetid://148840371\"\n        local ok, track = pcall(function() return humanoid:LoadAnimation(animation) end)\n        if not ok or not track then return false end\n        bg.track = track\n        track.Looped = true\n        track:Play()\n        track:AdjustSpeed(bg.speed)\n        bg.active = true\n        bg.conn = RunService.Heartbeat:Connect(function(deltaTime)\n            if not bg.active then return end\n            local victim = targetPlayer()\n            local vchar = victim and victim.Character\n            local vroot = vchar and vchar:FindFirstChild(\"HumanoidRootPart\")\n            local myChar = LocalPlayer.Character\n            local myRoot = myChar and myChar:FindFirstChild(\"HumanoidRootPart\")\n            if not (vroot and myRoot) then\n                stopBang()\n                return\n            end\n            -- Oscillate behind the target's back: +Z of the target's CFrame is\n            -- behind it, so we ride 0.7..1.6 studs back and thrust in/out.\n            bg.phase = bg.phase + deltaTime * bg.speed\n            local wave = (math.sin(bg.phase * 2) + 1) / 2\n            local depth = 0.7 + wave * 0.9\n            pcall(function()\n                myRoot.CFrame = vroot.CFrame * CFrame.new(0, 0, depth)\n            end)\n            if bg.track and not bg.track.IsPlaying then\n                pcall(function() bg.track:Play() end)\n            end\n        end)\n        return true\n    end\n\n    LocalPlayer.CharacterAdded:Connect(function()\n        if bg.active then stopBang() end\n    end)\n\n    local function playerNames()\n        local names = { \"None\" }\n        for _, player in ipairs(Players:GetPlayers()) do\n            if player ~= LocalPlayer then names[#names + 1] = player.Name end\n        end\n        table.sort(names, function(a, b) if a == \"None\" then return true elseif b == \"None\" then return false end return string.lower(a) < string.lower(b) end)\n        return names\n    end\n\n    local selector\n    pcall(function()\n        selector = section:AddDropdown(\"Bang Target\", playerNames(), function(name) bg.target = name end)\n    end)\n    pcall(function()\n        section:AddButton(\"Refresh Player List\", function()\n            if selector and selector.Refresh then pcall(function() selector:Refresh(playerNames(), bg.target) end) end\n        end)\n    end)\n    pcall(function()\n        section:AddToggle(\"Bang Player\", function(on)\n            if on == true then\n                if not startBang() then warn(\"[Noir Troll] Bang: no character or no target selected.\") end\n            else\n                stopBang()\n            end\n        end)\n    end)\n    pcall(function()\n        section:AddSlider(\"Bang Speed\", 1, 20, 10, function(v)\n            bg.speed = math.clamp(tonumber(v) or 10, 1, 20)\n            if bg.track then pcall(function() bg.track:AdjustSpeed(bg.speed) end) end\n        end)\n    end)\n    pcall(function()\n        section:AddKeybind(\"Bang Keybind\", \"G\", function()\n            if bg.active then stopBang() else startBang() end\n        end)\n    end)\n    pcall(function() section:AddLabel(\"Pick a target, hit Refresh if the list is stale, then enable. Stops automatically if the target leaves or you respawn.\") end)\nend\n"
